CREATE OR REPLACE FUNCTION app_private.attribute_command()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if session_user='ct_api' then
    new.created_by := app_private.verified_user();
    new.operation_id := nullif(current_setting('ct.operation_id',true),'')::uuid;
    if new.created_by is null or new.operation_id is null
      or new.tenant_id is distinct from app_private.command_scope() then
      raise exception 'invalid command attribution' using errcode='42501';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.protect_invariants()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_table_name='tenants' and tg_op <> 'DELETE' then
    if tg_op='UPDATE' and (new.id <> old.id or new.slug <> old.slug) then
      raise exception 'tenant_identity_immutable' using errcode='23514';
    end if;
    if not exists(select 1 from pg_catalog.pg_timezone_names where name=new.timezone) then
      raise exception 'invalid_timezone' using errcode='23514';
    end if;
  elsif tg_op='UPDATE' then
    if to_jsonb(new)->'tenant_id' is distinct from to_jsonb(old)->'tenant_id'
       or to_jsonb(new)->'user_id' is distinct from to_jsonb(old)->'user_id'
       or (tg_table_name='tenant_website_content_overrides'
         and to_jsonb(new)->'content_key' is distinct from to_jsonb(old)->'content_key') then
      raise exception 'account_identity_immutable' using errcode='23514';
    end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.protect_staff_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.role='owner' then
    raise exception 'owner_assignment_immutable' using errcode='23514';
  elsif tg_op='DELETE' then
    return old;
  elsif (new.tenant_id,new.user_id,new.role) is distinct from (old.tenant_id,old.user_id,old.role) then
    raise exception 'staff_identity_immutable' using errcode='23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.require_tenant_roots()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_tenant uuid;
begin
  v_tenant := case when tg_table_name = 'tenants' then (to_jsonb(new)->>'id')::uuid
    when tg_op = 'DELETE' then (to_jsonb(old)->>'tenant_id')::uuid else (to_jsonb(new)->>'tenant_id')::uuid end;
  if exists (select 1 from public.tenants where id = v_tenant) then
    if (select count(*) from public.tenant_staff_assignments where tenant_id = v_tenant and role = 'owner' and status = 'active') <> 1
       or not exists (select 1 from public.tenant_settings where tenant_id = v_tenant) then
      raise exception 'tenant_requires_owner_and_settings' using errcode = '23514';
    end if;
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION app_private.stamp_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor uuid;
begin
  if tg_op = 'INSERT' and tg_table_name = 'user_accounts' then
    actor := (to_jsonb(new)->>'user_id')::uuid;
  elsif session_user = 'ct_api' then
    actor := app_private.verified_user();
    if actor is null then
      raise exception 'verified actor required' using errcode = '42501';
    end if;
  else
    actor := auth.uid();
  end if;
  if tg_op = 'INSERT' then
    new.created_at := clock_timestamp();
    new.created_by := actor;
  else
    new.created_at := old.created_at;
    new.created_by := old.created_by;
  end if;
  new.updated_at := clock_timestamp();
  new.updated_by := actor;
  return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.stamp_first_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op='UPDATE' and old.first_approved_at is not null then
    if new.first_approved_at is distinct from old.first_approved_at then
      raise exception 'first_approval_immutable' using errcode='23514';
    end if;
  elsif new.first_approved_at is not null then
    raise exception 'first_approval_must_be_stamped' using errcode='23514';
  elsif new.standing='approved' then
    new.first_approved_at := clock_timestamp();
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.validate_command_details()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  fields text[];
  item record;
begin
  if new.action like '%.%' then
    if new.details <> '{}'::jsonb or (new.reason is not null and length(new.reason)>2000) then raise check_violation; end if;
    return new;
  end if;
  fields := case
    when new.action in ('community_join_requested','community_join_withdrawn','community_reactivation_requested','community_reactivation_withdrawn')
      then array['request_id']
    when new.action in ('community_approved','community_reactivated') then array['after_standing','request_id']
    when new.action in ('community_deactivated','community_suspended','community_removed','community_restriction_cleared')
      then array['before_standing','after_standing','before_restricted','after_restricted','request_id']
    when new.action='staff_created' then array['after_status']
    when new.action in ('staff_paused','staff_resumed','staff_revoked') then array['before_status','after_status']
    when new.action='staff_reappointed' then array['before_status','after_status','permissions']
    when new.action='staff_permissions_changed' then array['permissions']
    when new.action='community_permissions_changed' then array['before','after']
  end;
  if fields is null or jsonb_typeof(new.details)<>'object' or new.details-fields <> '{}'::jsonb
    or (new.reason is not null and length(new.reason)>2000) then raise check_violation; end if;
  if new.action in ('community_approved','community_reactivated') then
    if not new.details ?| fields then raise check_violation; end if;
  elsif new.action in ('community_deactivated','community_suspended','community_removed','community_restriction_cleared') then
    if not new.details ?& array['before_standing','after_standing','before_restricted','after_restricted'] then raise check_violation; end if;
  elsif not new.details ?& fields then raise check_violation;
  end if;
  for item in select * from jsonb_each(new.details) loop
    case item.key
      when 'before_standing','after_standing' then
        if item.value not in ('"pending"','"approved"','"suspended"','"inactive"') then raise check_violation; end if;
      when 'before_status','after_status' then
        if item.value not in ('"active"','"paused"','"revoked"') then raise check_violation; end if;
      when 'before_restricted','after_restricted','before','after' then
        if jsonb_typeof(item.value)<>'boolean' then raise check_violation; end if;
      when 'request_id' then
        if jsonb_typeof(item.value)<>'string' then raise check_violation; end if;
        perform (new.details->>'request_id')::uuid;
      when 'permissions' then
        if jsonb_typeof(item.value)<>'object' or item.value-array['can_approve_users','can_grant_staff','can_modify_content','can_discipline_users','can_discipline_staff','can_manage_community_activities','can_manage_official_activities','can_manage_community_permissions','can_see_private_events','can_manage_settings','can_moderate_all_chats','can_audit_community_accounts','can_audit_staff_accounts'] <> '{}'::jsonb
          or exists (select from jsonb_each(item.value) p where jsonb_typeof(p.value)<>'object'
            or p.value-array['before','after'] <> '{}'::jsonb or jsonb_typeof(p.value->'before') is distinct from 'boolean'
            or jsonb_typeof(p.value->'after') is distinct from 'boolean') then raise check_violation; end if;
    end case;
  end loop;
  return new;
end $function$
